/* Small, source-independent guild decorations; no reading state or task mutations. */
(()=>{'use strict';if(document.getElementById('guild-reader-atmosphere-style'))return;
const crest='data:image/png;base64,',happy='data:image/png;base64,',style=document.createElement('style');style.id='guild-reader-atmosphere-style';style.textContent=`
.guild-reader-emblem{display:inline-block;width:30px;height:30px;object-fit:contain;flex:0 0 30px}.guild-reader-atmosphere{display:flex;align-items:center;gap:12px;margin:0 0 18px;padding:10px 14px;background:#faf3e2;border:1px solid #e2d0ac;border-left:3px solid #ac833f;border-radius:6px;color:#82612e;max-width:610px}.guild-reader-atmosphere img{width:38px;height:38px;object-fit:contain;flex:0 0 38px}.guild-reader-atmosphere strong{display:block;font:600 14px/1.7 'Microsoft YaHei',sans-serif;color:#8d3c4b}.guild-reader-atmosphere small{display:block;font:400 12px/1.6 'Microsoft YaHei',sans-serif;color:#927a53}.guild-reader-companion{display:flex;gap:12px;align-items:center;padding:12px 14px;border:1px solid #c9d6dc;border-top:2px solid #7b9cad;background:#f3f8fa;border-radius:7px;margin-top:14px}.guild-reader-companion img{width:42px;height:58px;object-fit:contain;image-rendering:pixelated;flex:0 0 42px}.guild-reader-companion strong{display:block;font:500 13px/1.7 'Microsoft YaHei',sans-serif;color:#5a7583}.guild-reader-companion small{font:400 12px/1.65 'Microsoft YaHei',sans-serif;color:#7d8b8e}.guild-reader-rule{width:72px;height:3px;background:linear-gradient(90deg,#a84d5c 0 48%,transparent 48% 55%,#b79551 55%);margin:12px 0 0}
@media(max-width:750px){.guild-reader-atmosphere{padding:9px 11px;gap:9px}.guild-reader-atmosphere img{width:30px;height:30px;flex-basis:30px}.guild-reader-companion{margin-top:8px}.guild-reader-emblem{width:26px;height:26px;flex-basis:26px}}
@media print{.guild-reader-atmosphere,.guild-reader-companion,.guild-reader-emblem,.guild-reader-rule{display:none!important}}`;
document.head.append(style);
const image=(src,alt,cls)=>{const im=document.createElement('img');im.src=src;im.alt=alt;if(cls)im.className=cls;im.decoding='async';im.onerror=()=>im.hidden=true;return im};
const brand=document.querySelector('.brand');if(brand){brand.querySelector('.guild-book-mark')?.remove();brand.prepend(image(crest,'妖精的尾巴公会徽章','guild-reader-emblem'))}
const title=document.querySelector('.title');if(title){const box=document.createElement('div');box.className='guild-reader-atmosphere';box.append(image(crest,'妖尾公会徽章'));const copy=document.createElement('div'),name=document.createElement('strong'),sub=document.createElement('small');name.textContent='妖精的尾巴 · 公会研读卷宗';sub.textContent='核对原文，留好线索，让每一页都有收获。';copy.append(name,sub);box.append(copy);title.prepend(box);const rule=document.createElement('div');rule.className='guild-reader-rule';rule.setAttribute('aria-hidden','true');title.append(rule)}
const aside=document.querySelector('aside');if(aside){const box=document.createElement('div');box.className='guild-reader-companion';const copy=document.createElement('div'),name=document.createElement('strong'),sub=document.createElement('small');name.textContent='研读角伙伴 · 哈比';sub.textContent='读到有意思的地方，记在下方学习笔记里。';copy.append(name,sub);box.append(image(happy,'哈比的像素小人'),copy);aside.append(box)}
})();

/* Runtime addition upgrades existing archived reading pages without rewriting their content. */
(()=>{'use strict';
 // Share position with the parent without changing reading data or issuing workflow requests.
 if(!window.GuildWorkbenchNavigation){
  const navNonce=new URL(location.href).searchParams.get('context');
  if(parent!==window&&navNonce){
   let navTimer=null,restoringPosition=false,restoreVersion=0;
   const report=()=>{if(restoringPosition)return;parent.postMessage({type:'guild-literature-navigation',nonce:navNonce,path:location.pathname+location.search,scrollY:Math.round(window.scrollY)},'*')};
   const scheduleReport=()=>{clearTimeout(navTimer);navTimer=setTimeout(report,200)};
   const restore=async y=>{const version=++restoreVersion;restoringPosition=true;await Promise.race([Promise.allSettled([...document.images].filter(im=>!im.complete).map(im=>new Promise(resolve=>{im.addEventListener('load',resolve,{once:true});im.addEventListener('error',resolve,{once:true})}))),new Promise(resolve=>setTimeout(resolve,2000))]);requestAnimationFrame(()=>requestAnimationFrame(()=>{if(version!==restoreVersion)return;window.scrollTo(0,y);restoringPosition=false;report()}))};
   window.GuildWorkbenchNavigation={report,scheduleReport};
   window.addEventListener('message',event=>{if(event.source!==parent||event.data?.type!=='guild-literature-restore-position'||event.data.nonce!==navNonce)return;const y=event.data.scrollY;if(typeof y==='number'&&Number.isFinite(y)&&y>=0&&y<=10000000)void restore(y)});
   window.addEventListener('scroll',scheduleReport,{passive:true});window.addEventListener('hashchange',scheduleReport);window.addEventListener('popstate',scheduleReport);window.addEventListener('pagehide',report);
   if(document.readyState==='complete')scheduleReport();else window.addEventListener('load',scheduleReport,{once:true});
  }
 }

 const token=window.GUILD_READING_TOKEN,params=new URL(location.href).searchParams,id=params.get('id'),context=params.get('context');if(!token||!id)return;
 const host=document.querySelector('.guild-link');if(!host)return;
 const restartMessage='当前文献服务尚未加载研读委托功能，请先手动重启本地文献服务，再刷新本页。';
 const capability=fetch('/api/workbench-capabilities',{cache:'no-store'}).then(async response=>{if(!response.ok)return false;return(await response.json()).readingTaskWorkflow===true}).catch(()=>false);
 async function api(route,body){const response=await fetch('/api/'+route,{method:'POST',headers:{'Content-Type':'application/json','X-Guild-Token':token},body:JSON.stringify(body),signal:AbortSignal.timeout(20000)});const result=await response.json();if(!response.ok)throw Error(result.error||'未保存');return result;}
 function notifyTaskReady(){if(parent!==window&&context)parent.postMessage({type:'guild-literature-task-ready',nonce:context,paperId:id},'*')}
 function libraryUrl(){const url=new URL('/',location.origin);url.searchParams.set('view','library');url.searchParams.set('paper',id);if(context)url.searchParams.set('context',context);return url.href}
 async function flush(){if(typeof window.GuildWorkbenchSave==='function')await window.GuildWorkbenchSave();else throw Error('此旧版页面无法确认最新笔记已同步，请先导出备份并更新阅读工作台。')}
 // Old archived pages used new tabs and sent "return to guild" to the literature service.
 // Keep their existing state and replace only the destination behavior.
 for(const link of host.querySelectorAll('.guild-actions a')){const text=link.textContent||'';if(!/返回公会/.test(text))continue;link.removeAttribute('target');link.removeAttribute('rel');const view=/研读角/.test(text)?'library':'guild';link.href=view==='library'?libraryUrl():'#';link.addEventListener('click',async event=>{event.preventDefault();try{if(typeof window.GuildWorkbenchReturn==='function'){await window.GuildWorkbenchReturn(view);return}await flush();if(view==='library'){location.assign(libraryUrl());return}if(parent!==window&&context){parent.postMessage({type:'guild-literature-return',nonce:context,paperId:id},'*');return}if(!await capability)throw Error(restartMessage);const result=await api('open-guild',{paperId:id,view:'guild'});status.textContent=result.message}catch(error){status.textContent=error.message}})}
 const startRow=document.createElement('div');startRow.className='guild-actions';const start=document.createElement('button');start.type='button';start.className='is-primary';start.textContent='开始阅读';const workflowStatus=document.createElement('p');workflowStatus.setAttribute('role','status');start.disabled=true;startRow.append(start);host.append(startRow,workflowStatus);
 let workflowEnabled=false;
 function showWorkflow(workflow,message){if(!workflowEnabled){start.disabled=true;workflowStatus.textContent=restartMessage;return}const state=workflow?.state;if(workflow?.error){start.textContent='重试建立研读委托';start.disabled=false;workflowStatus.textContent=String(workflow.error);return}if(state==='completed'){start.textContent='研读已完成';start.disabled=true}else{start.textContent=state==='started'?'继续阅读':state==='pending'?'委托待公会接收 · 继续阅读':'开始阅读';start.disabled=false}workflowStatus.textContent=message||((workflow?.mode==='existing'||workflow?.mode==='manual')?'沿用已有委托，研读记录保留；普通委托仍由你在公会内确认完成。':state==='pending'?'开始请求已保存，关联委托等待主公会接收；尚未确认创建完成。':state==='started'?'关联研读委托已创建，可继续阅读。':state==='completed'?'研读与关联委托已完成。':'点击开始阅读，自动建立对应的公会研读委托。')}
 start.onclick=async()=>{start.disabled=true;try{if(!await capability)throw Error(restartMessage);const result=await api('reading-start',{id,embedded:parent!==window});notifyTaskReady();showWorkflow(result.workflow,result.message)}catch(error){workflowStatus.textContent=error.message;start.disabled=false}};
 const box=document.createElement('details'),heading=document.createElement('summary');heading.textContent='✦ 完成研读 · 向公会递交成果';
 const note=document.createElement('textarea');note.rows=3;note.placeholder='用至少8字记录这篇论文对你有用的收获';note.setAttribute('aria-label','研读收获');note.style.cssText='width:100%;box-sizing:border-box;margin:10px 0';
 const label=document.createElement('label'),check=document.createElement('input');check.type='checkbox';label.append(check,document.createTextNode('我已核对这份PDF的身份，并完成上述研读'));
 const button=document.createElement('button');button.type='button';button.className='is-primary';button.textContent='确认完成研读并返回研读角';button.disabled=true;const status=document.createElement('p');status.setAttribute('role','status');
 box.append(heading,note,label,document.createElement('p'),button,status);host.append(box);
 void capability.then(enabled=>{workflowEnabled=enabled;if(!enabled){start.disabled=true;button.disabled=true;workflowStatus.textContent=restartMessage;status.textContent=restartMessage}else{button.disabled=false;showWorkflow(null)}});
 void fetch('/api/workbench-progress?id='+encodeURIComponent(id),{headers:{'X-Guild-Token':token},cache:'no-store'}).then(async response=>{const p=await response.json();if(!response.ok)throw Error(p.error||'未能读取研读状态');await capability;showWorkflow(p.workflow);const m=p.metric;if(!m)return;const line=document.createElement('p'),parts=[];if(Number.isFinite(m.value))parts.push(m.year+' JIF '+m.value+(m.reference?'（参考）':''));for(const[k,name]of [['jcr','SCI/JCR'],['cas','中科院'],['xr','新锐']]){const v=m.partitions?.[k];if(v)parts.push(name+' '+v.zone+(k==='jcr'?'':'区')+' · '+v.year+(v.reference?'（参考）':''));}line.textContent=parts.join(' · ');host.prepend(line);}).catch(error=>{workflowStatus.textContent=error.message+'；可点击开始阅读重试。'});
 button.onclick=async()=>{if(!await capability){status.textContent=restartMessage;button.disabled=true;return}if(!check.checked){status.textContent='请先确认PDF身份与研读完成';return}if(note.value.trim().length<8){status.textContent='请写至少8字的具体研读收获';return}button.disabled=true;try{
  await flush();
  const result=await api('reading-claim',{id,kind:'read',takeaway:note.value.trim(),confirmed:true,identityConfirmed:true,embedded:parent!==window});notifyTaskReady();status.textContent=result.message||'研读成果已记录，正在返回研读角。';button.textContent='研读成果已记录';
  if(result.workflow)showWorkflow(result.workflow,result.message);
  location.assign(libraryUrl());
 }catch(error){status.textContent=error.message;button.disabled=false;}};
})();
